  var level=h.getLevel();var server=level.getServer();server.tickRateManager().setTickRate(200);var project=ConstructionService.store(server).projects().stream().filter(q->q.blueprint().toString().equals(Profession.ALCHEMIST.buildingId())).findFirst().orElseThrow();var id=UUID.nameUUIDFromBytes("PremisesThirdStudent".getBytes(java.nio.charset.StandardCharsets.UTF_8));var p=ClaimRuntimeTests.vanillaPlayer(level,id,"ThirdStudent");server.getPlayerList().deop(p.getGameProfile());h.assertTrue(!p.hasPermissions(2),"Native Alchemist actor is an ordinary survival player");var b=BlueprintRegistry.get(project.blueprint(),1);var center=project.origin().offset(b.rotate(new BlockPos(7,1,6),project.rotation()));for(int x=(center.getX()-10)>>4;x<=(center.getX()+10)>>4;x++)for(int z=(center.getZ()-10)>>4;z<=(center.getZ()+10)>>4;z++)level.getChunk(x,z);
