  Walk(GameTestHelper h,ServerPlayer p,ConstructionStore.Project project,BlockPos center){this.h=h;this.p=p;this.project=project;this.center=center;level=h.getLevel();BrewingStandBlockEntity found=null;for(var at:BlockPos.betweenClosed(center.offset(-8,-1,-8),center.offset(8,2,8)))if(level.getBlockEntity(at) instanceof BrewingStandBlockEntity actual)found=actual;if(found==null)throw new IllegalStateException("Original Alchemist stand absent");stand=found;}
  String diagnostic(){var b=BlueprintRegistry.get(project.blueprint(),1);String mismatch="";for(var block:b.blocks(project.rotation())){var at=project.origin().offset(block.offset());if(!b.matches(level.getBlockState(at),block.state())){mismatch=at+" current="+level.getBlockState(at)+" expected="+block.state();break;}}var entity=level.getEntity(project.npc());return "mismatch="+mismatch+",npc="+entity+",issued="+project.npcIssued()+",dead="+project.npcDead();}
