  int menuSlot(BrewingStandMenu menu,int slot){for(int n=5;n<menu.slots.size();n++)if(menu.getSlot(n).container==p.getInventory()&&menu.getSlot(n).getContainerSlot()==slot)return n;throw new IllegalStateException("Native inventory slot absent");}
  void insert(BrewingStandMenu menu,int target,ItemStack stack){int amount=stack.getCount();int at=menuSlot(menu,supply(stack));menu.clicked(at,0,ClickType.PICKUP,p);menu.clicked(target,0,ClickType.PICKUP,p);h.assertTrue(menu.getCarried().isEmpty()&&stand.getItem(target).getCount()==amount,"Real native inventory/cursor transfer into stand");}
  void tick(int n){for(int i=0;i<n;i++)BrewingStandBlockEntity.serverTick(level,stand.getBlockPos(),level.getBlockState(stand.getBlockPos()),stand);}
