  void inspect(String id)throws Exception{var admin=level.getServer().getPlayerList().getPlayer(project.owner());if(admin==null)admin=ClaimRuntimeTests.vanillaPlayer(level,project.owner(),project.ownerName());level.getServer().getPlayerList().op(admin.getGameProfile());BlacksmithRepairRuntime.near(p,center);BlacksmithRepairRuntime.near(admin,center);var q=ProfessionInspectionService.review(admin,p,id,center,"Inspected actual accessible charged native fuel water storage and real brewing records");ProfessionInspectionService.confirm(admin,q);}
  void run()throws Exception{
   var store=CommerceService.store(p.server);var track=store.professions(p.getUUID()).track(Profession.ALCHEMIST);h.assertTrue(store.professions(p.getUUID()).isActive(Profession.ALCHEMIST),"Original Alchemist enrollment retained");if(track.completedQuestIds().contains("kingdom_smp:alchemist/a08")){h.assertTrue(track.xp()>=800&&track.completedQuestIds().size()>=8&&store.professions(p.getUUID()).rank(Profession.ALCHEMIST,ProfessionQuestService.catalog())==ProfessionRank.JOURNEYMAN,"All8earned800XP/Journeyman restore");h.assertTrue(ConstructionService.structureIntact(level,project)&&level.getEntity(project.npc()) instanceof com.mohymods.kingdomsmp.npc.ReeveEntity,"Same laboratory and Nessa restore: "+diagnostic());CommerceService.verifyReceipt(p);if(Boolean.getBoolean("kingdom.testAlchemyReagents")){ReagentRuntime.run(h,p,project);return;}if(Boolean.getBoolean("kingdom.testAlchemyJourneyman"))journeyman();if(Boolean.getBoolean("kingdom.testAlchemyMixed"))mixed();com.mojang.logging.LogUtils.getLogger().info("ALCHEMY_RESTART_PASSED: original8earned800XP/Journeyman/exact native outputs and spent receipts/charged stand/water/original laboratory and Nessa survive real dedicated JVM without replay");h.succeed();return;}
   for(int x=(center.getX()-9)>>4;x<=(center.getX()+9)>>4;x++)for(int z=(center.getZ()-9)>>4;z<=(center.getZ()+9)>>4;z++){var at=new BlockPos(x*16,center.getY(),z*16);ClaimRuntimeTests.ftbUnclaim(level,at);ClaimRuntimeTests.ftbClaim(p,at);ClaimRuntimeTests.opacClaim(level,p.getUUID(),at);} // Explicit private owner consent/claim policy, source unchanged.
   if(!track.completedQuestIds().contains("kingdom_smp:alchemist/a01")){
    DimensionTravelRuntimeTests.seed(p.server,5);h.assertTrue(track.xp()==100,"Only the actual earlier daily commission exists");boolean refused=false;try{inspect("kingdom_smp:alchemist/a01");}catch(IllegalStateException expected){refused=true;}h.assertTrue(refused,"Uncharged furniture cannot replace real blaze fuel/water");
    BlockPos cauldron=null;for(var at:BlockPos.betweenClosed(center.offset(-8,-1,-8),center.offset(8,2,8)))if(level.getBlockState(at).is(Blocks.CAULDRON))cauldron=at.immutable();h.assertTrue(cauldron!=null,"Use original laboratory cauldron");BlacksmithRepairRuntime.near(p,cauldron);var held=p.getMainHandItem().copy();p.setItemInHand(InteractionHand.MAIN_HAND,new ItemStack(Items.WATER_BUCKET));p.gameMode.useItemOn(p,level,p.getMainHandItem(),InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(cauldron),Direction.UP,cauldron,false));h.assertTrue(level.getBlockState(cauldron).is(Blocks.WATER_CAULDRON)&&p.getMainHandItem().is(Items.BUCKET),"Actual water bucket fills native cauldron at intact original laboratory");p.setItemInHand(InteractionHand.MAIN_HAND,held);
    var menu=menu();insert(menu,4,new ItemStack(Items.BLAZE_POWDER));tick(1);h.assertTrue(((NativeBrewingAccess)stand).kingdom$fuel()==20&&stand.getItem(4).isEmpty(),"Real native blaze fuel debit charges20brews");p.closeContainer();h.assertTrue(ConstructionService.structureIntact(level,project),"Normal filled cauldron preserves building integrity");inspect("kingdom_smp:alchemist/a01");negativeBatches();start("kingdom_smp:alchemist/a02");tick(101);h.assertTrue(((NativeBrewingAccess)stand).kingdom$brewTime()==300&&((BrewJobHolder)stand).kingdom$brewJob().getInt("stage")==1,"Actual partially brewed bound operation is saved before restart");p.closeContainer();com.mojang.logging.LogUtils.getLogger().info("ALCHEMY_PENDING_PREPARED: native water bucket/fuel debit/laboratory inspection, actual player input/reagent transfers and partial native brewing300ticks/owner/band proof for restart; no objective/output injection");h.succeed();return;
   }
   h.assertTrue(track.xp()==200&&((BrewJobHolder)stand).kingdom$brewJob().getInt("stage")>=1,"Second JVM retains real pending batch and earned inspection");tick(((NativeBrewingAccess)stand).kingdom$brewTime());claimRevocation();collect("kingdom_smp:alchemist/a02");for(var id:BrewQuests.ids().stream().filter(id->id.contains("/a")).sorted().toList()){int batches=id.endsWith("a02")?3:4;for(int n=0;n<batches;n++){start(id);tick(401);collect(id);}counter();var q=ProfessionService.review(p,"enchanted:"+id);ProfessionService.confirm(p,q.nonce());h.assertTrue(store.professions(p.getUUID()).track(Profession.ALCHEMIST).completedQuestIds().contains(id),"Real native12potion permanent delivery and100XP");}
   var menu=menu();insert(menu,4,new ItemStack(Items.BLAZE_POWDER));tick(1);p.closeContainer();inspect("kingdom_smp:alchemist/a08");h.assertTrue(store.professions(p.getUUID()).track(Profession.ALCHEMIST).xp()==800&&store.professions(p.getUUID()).track(Profession.ALCHEMIST).completedQuestIds().size()==8,"All8genuine Apprentice proofs earn800XPonce");CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("ALCHEMY_APPRENTICE_NATIVE_PASSED: native partial brew restart, sixty real commissioned potions/actual reagent and fuel costs/authenticated collection/five12potion permanent native deliveries, actual fueled-water/storage inspection,8earned800XP/Journeyman/original Nessa; physical inputs and native tick acceleration only");h.succeed();
  }
  void negativeBatches(){for(int scenario:new int[]{0,1,2}){start("kingdom_smp:alchemist/a02");if(scenario==2){tick(1);var moved=((BrewJobHolder)stand).kingdom$brewJob();moved.putLong("position",stand.getBlockPos().east().asLong());((BrewJobHolder)stand).kingdom$brewJob(moved);tick(400);}else if(scenario==1){tick(1);var bad=new net.minecraft.nbt.CompoundTag();bad.putInt("schema",999);((BrewJobHolder)stand).kingdom$brewJob(bad);tick(400);}else{var actual=stand.removeItem(3,1);h.assertTrue(((BrewJobHolder)stand).kingdom$brewJob().isEmpty(),"Successful native removal invalidates unfinished operator lineage");stand.setItem(3,actual);tick(401);}h.assertTrue(stand.getItem(3).isEmpty()&&BrewingEvidence.potion(stand.getItem(0)).equals("minecraft:awkward"),"Invalid/corrupt evidence cannot interrupt actual native reagent consumption/output");var menu=menu();for(int i=0;i<3;i++){h.assertTrue(!stand.getItem(i).getOrDefault(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.EMPTY).copyTag().contains(EnchantedToolService.KEY),"Unattributed or corrupt batch produces no authoritative output marker");menu.quickMoveStack(p,i);}p.closeContainer();}h.assertTrue(CommerceService.store(p.server).professions(p.getUUID()).track(Profession.ALCHEMIST).xp()==200,"No preview, corrupted evidence or raw potion may fabricate XP");}
  void claimRevocation()throws Exception{var expected=stand.getItem(0).copy();var marker=expected.getOrDefault(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.EMPTY).copyTag().getCompound(EnchantedToolService.KEY);var other=level.getServer().getPlayerList().getPlayer(project.owner());if(other==null)other=ClaimRuntimeTests.vanillaPlayer(level,project.owner(),project.ownerName());ClaimRuntimeTests.ftbUnclaim(level,stand.getBlockPos());ClaimRuntimeTests.ftbClaim(other,stand.getBlockPos());var menu=menu();menu.quickMoveStack(p,0);h.assertTrue(!CommerceService.store(p.server).matchesNativeOutput(marker.getUUID("id"),p.getUUID(),"kingdom_smp:alchemist/a02",(net.minecraft.nbt.CompoundTag)expected.save(p.registryAccess())),"Revoked current claim denies authentication even if another native caller extracts the real output");int slot=-1;for(int i=0;i<36;i++)if(ItemStack.matches(p.getInventory().getItem(i),expected))slot=i;h.assertTrue(slot>=0,"Actual extracted native output remains in inventory");stand.setItem(0,p.getInventory().removeItem(slot,1));ClaimRuntimeTests.ftbUnclaim(level,stand.getBlockPos());ClaimRuntimeTests.ftbClaim(p,stand.getBlockPos());p.closeContainer();}
  void journeyman()throws Exception{var store=CommerceService.store(p.server);var track=store.professions(p.getUUID()).track(Profession.ALCHEMIST);var ids=List.of("kingdom_smp:alchemist/j01","kingdom_smp:alchemist/j02");if(track.completedQuestIds().containsAll(ids)){h.assertTrue(track.xp()==1200&&track.completedQuestIds().size()==10,"Two real Jcommissions restore without replay");com.mojang.logging.LogUtils.getLogger().info("ALCHEMY_JOURNEYMAN_RESTART_PASSED: same10earned1200XP/long-fire and strong-healing exact spent native outputs/current native receipt/original Nessa and laboratory restored");return;}h.assertTrue(track.xp()==800,"Only original8earned Apprentice proofs precede native Journeyman production");DimensionTravelRuntimeTests.seed(p.server,5);h.assertTrue(!NativeOutputQuests.eligible(p,ids.getFirst(),true),"Tier5cannot qualify for Tier6Journeyman brewing");DimensionTravelRuntimeTests.seed(p.server,6);for(var id:ids){for(int batch=0;batch<4;batch++){start(id);tick(401);collect(id);}counter();var q=ProfessionService.review(p,"enchanted:"+id);ProfessionService.confirm(p,q.nonce());}h.assertTrue(store.professions(p.getUUID()).track(Profession.ALCHEMIST).xp()==1200&&store.professions(p.getUUID()).track(Profession.ALCHEMIST).completedQuestIds().size()==10,"Actual24native long/strong potions physically consumed for400XPonce");CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("ALCHEMY_JOURNEYMAN_NATIVE_PASSED: actual Tier5refusal/Tier6native redstone duration and glowstone strength recipes/fuel/reagents/twenty-four authenticated native potions/permanent12each delivery/400XPonce to10earned1200XP; raw physical inputs/native tick acceleration only");}
  void mixed()throws Exception{var store=CommerceService.store(p.server);var track=store.professions(p.getUUID()).track(Profession.ALCHEMIST);if(track.completedQuestIds().containsAll(List.of(BrewQuests.UNDERWATER,BrewQuests.SPLASH))){h.assertTrue(track.xp()==1600&&track.completedQuestIds().size()==12,"Actual two new Jobjectives restore with old10proofs and no replay");CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("ALCHEMY_MIXED_RESTART_PASSED: original12earned1600XP/mixed8+8potion and12beneficial splash native spent rights/unchanged original Nessa-lab/private stock/native receipt restore");return;}h.assertTrue(track.xp()==1200&&track.completedQuestIds().size()==10,"Start from actual earlier earned10proofs");var water=BrewQuests.recipes(BrewQuests.UNDERWATER).stream().filter(r->r.output().equals("water_breathing")).findFirst().orElseThrow();var vision=BrewQuests.recipes(BrewQuests.UNDERWATER).stream().filter(r->r.output().equals("night_vision")).findFirst().orElseThrow();for(int n=0;n<6;n++){start(water);tick(401);collect(water.quest());}counter();boolean denied=false;try{ProfessionService.review(p,"enchanted:"+BrewQuests.UNDERWATER);}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied,"Eighteen genuine native water-breathing outputs cannot substitute for the missing night-vision quota");
   net.minecraft.world.Container storage=null;for(var at:BlockPos.betweenClosed(center.offset(-8,-1,-8),center.offset(8,2,8)))if(level.getBlockEntity(at) instanceof BarrelBlockEntity barrel){storage=barrel;break;}h.assertTrue(storage!=null,"Original ordinary storage exists");int moved=0;for(int i=0;i<36&&moved<9;i++){var stack=p.getInventory().getItem(i);if(!stack.is(Items.POTION)||!BrewingEvidence.potion(stack).equals("minecraft:water_breathing"))continue;int free=-1;for(int j=0;j<storage.getContainerSize();j++)if(storage.getItem(j).isEmpty()){free=j;break;}h.assertTrue(free>=0,"Private physical stash has capacity");storage.setItem(free,p.getInventory().removeItem(i,1));moved++;}storage.setChanged();h.assertTrue(moved==9,"Move real extra native outputs to ordinary barrel, never duplicate/delete them");for(int n=0;n<3;n++){start(vision);tick(401);collect(vision.quest());}counter();int before=authenticatedCount(BrewQuests.UNDERWATER);var q=ProfessionService.review(p,"enchanted:"+BrewQuests.UNDERWATER);ProfessionService.confirm(p,q.nonce());h.assertTrue(before-authenticatedCount(BrewQuests.UNDERWATER)==16,"Only8of each native family permanently removed; leftovers retain distinct unspent identities");for(int n=0;n<4;n++){start(BrewQuests.recipes(BrewQuests.SPLASH).subList(0,3));tick(401);collect(BrewQuests.SPLASH);}counter();q=ProfessionService.review(p,"enchanted:"+BrewQuests.SPLASH);ProfessionService.confirm(p,q.nonce());h.assertTrue(store.professions(p.getUUID()).track(Profession.ALCHEMIST).xp()==1600&&store.professions(p.getUUID()).track(Profession.ALCHEMIST).completedQuestIds().size()==12,"Native8+8and12splash deliveries earn400XPonce, no future rank invented");CommerceService.verifyReceipt(p);com.mojang.logging.LogUtils.getLogger().info("ALCHEMY_MIXED_NATIVE_PASSED: eighteen actual native water brews refuse single-family substitution; physical surplus stashed, nine actual native night-vision brews, distinct8+8native consumed output identities,12real gunpowder-beneficial splash native conversions and delivery/400XPonce to12earned1600XP; raw inputs/native tick acceleration only");}
  int authenticatedCount(String quest){int count=0;var store=CommerceService.store(p.server);for(int i=0;i<36;i++){var item=p.getInventory().getItem(i);if(item.isEmpty())continue;var tag=item.getOrDefault(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.EMPTY).copyTag().getCompound(EnchantedToolService.KEY);if(tag.hasUUID("id")&&store.matchesNativeOutput(tag.getUUID("id"),p.getUUID(),quest,(net.minecraft.nbt.CompoundTag)item.save(p.registryAccess())))count++;}return count;}
  void start(String quest){start(BrewQuests.get(quest));}
  void start(BrewQuests.Recipe recipe){start(List.of(recipe,recipe,recipe));}
  void start(List<BrewQuests.Recipe> recipes){var recipe=recipes.getFirst();String quest=recipe.quest();var menu=menu();if(((NativeBrewingAccess)stand).kingdom$fuel()==0){insert(menu,4,new ItemStack(Items.BLAZE_POWDER));tick(1);}for(int i=0;i<3;i++){var potion=new ItemStack(Items.POTION);var holder=p.registryAccess().registryOrThrow(Registries.POTION).getHolderOrThrow(net.minecraft.resources.ResourceKey.create(Registries.POTION,net.minecraft.resources.ResourceLocation.withDefaultNamespace(recipes.get(i).input())));potion.set(net.minecraft.core.component.DataComponents.POTION_CONTENTS,new PotionContents(holder));insert(menu,i,potion);}insert(menu,3,new ItemStack(BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.withDefaultNamespace(recipe.reagent()))));h.assertTrue(((BrewJobHolder)stand).kingdom$brewJob().getString("quest").equals(quest),"Only real personal reagent insertion binds native batch");}
  void collect(String quest){h.assertTrue(((BrewJobHolder)stand).kingdom$brewJob().getInt("stage")==2&&stand.getItem(3).isEmpty(),"Actual successful native cycle consumes reagent and authenticates completed source");var menu=menu();for(int i=0;i<3;i++){var output=stand.getItem(i).copy();h.assertTrue(output.getCount()==1&&BrewQuests.recipes(quest).stream().anyMatch(r->BrewingEvidence.potion(output).equals("minecraft:"+r.output())&&output.is(BuiltInRegistries.ITEM.get(net.minecraft.resources.ResourceLocation.parse(r.item())))),"Correct actual native potion result");var marker=output.getOrDefault(net.minecraft.core.component.DataComponents.CUSTOM_DATA,net.minecraft.world.item.component.CustomData.EMPTY).copyTag().getCompound(EnchantedToolService.KEY);h.assertTrue(!CommerceService.store(p.server).matchesNativeOutput(marker.getUUID("id"),p.getUUID(),quest,(net.minecraft.nbt.CompoundTag)output.save(p.registryAccess())),"Uncollected stand preview cannot be delivered");menu.quickMoveStack(p,i);h.assertTrue(CommerceService.store(p.server).matchesNativeOutput(marker.getUUID("id"),p.getUUID(),quest,(net.minecraft.nbt.CompoundTag)output.save(p.registryAccess())),"Only successful native extraction binds exact output to operator");}p.closeContainer();}
